    "branding_json" TEXT NOT NULL DEFAULT ('{}'),
    "settings_json" TEXT NOT NULL DEFAULT ('{}'),
    "OnboardingStateJson" TEXT NULL,
    "OnboardingCurrentStep" INTEGER NULL,
    "OnboardingTemplateId" TEXT NULL,
    "OnboardingStatus" TEXT NOT NULL DEFAULT 'not_started',
    "finance_seed_status" TEXT NOT NULL DEFAULT 'not_seeded',
    "finance_seed_status_updated_at" TEXT NOT NULL,
    "finance_seeded_at" TEXT NULL,
    "OnboardingLastSavedUtc" TEXT NULL,
    "OnboardingCompletedUtc" TEXT NULL,
    "OnboardingAbandonedUtc" TEXT NULL,
