    "UpdatedUtc" TEXT NOT NULL,
    "is_demo_tenant" INTEGER NOT NULL DEFAULT 0,
    "demo_scenario_key" TEXT NULL,
    "demo_scenario_version" INTEGER NULL,
    CONSTRAINT "CK_companies_demo_marker" CHECK (is_demo_tenant = 0 OR (demo_scenario_key IS NOT NULL AND demo_scenario_version >= 1)),
    CONSTRAINT "CK_companies_finance_seed_status" CHECK (finance_seed_status IN ('not_seeded', 'seeding', 'seeded', 'failed'))
);


