CREATE TABLE "detected_bills" (
    "id" TEXT NOT NULL CONSTRAINT "PK_detected_bills" PRIMARY KEY,
    "company_id" TEXT NOT NULL,
    "supplier_name" TEXT NULL,
    "supplier_org_number" TEXT NULL,
    "invoice_number" TEXT NULL,
    "invoice_date" TEXT NULL,
    "due_date" TEXT NULL,
    "currency" TEXT NULL,
    "total_amount" decimal(18,2) NULL,
    "vat_amount" decimal(18,2) NULL,
    "payment_reference" TEXT NULL,
    "bankgiro" TEXT NULL,
    "plusgiro" TEXT NULL,
    "iban" TEXT NULL,
    "bic" TEXT NULL,
    "confidence" decimal(5,4) NULL,
    "confidence_level" TEXT NOT NULL,
    "validation_status" TEXT NOT NULL,
    "review_status" TEXT NOT NULL,
    "requires_review" INTEGER NOT NULL,
    "is_eligible_for_approval_proposal" INTEGER NOT NULL,
    "validation_status_persisted" INTEGER NOT NULL,
