    CONSTRAINT "AK_accounting_migration_conflicts_company_id_id" UNIQUE ("company_id", "id"),
    CONSTRAINT "FK_accounting_migration_conflicts_accounting_migration_runs_company_id_migration_run_id" FOREIGN KEY ("company_id", "migration_run_id") REFERENCES "accounting_migration_runs" ("company_id", "id"),
    CONSTRAINT "FK_accounting_migration_conflicts_companies_company_id" FOREIGN KEY ("company_id") REFERENCES "companies" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_accounting_migration_conflicts_finance_fiscal_periods_company_id_fiscal_period_id" FOREIGN KEY ("company_id", "fiscal_period_id") REFERENCES "finance_fiscal_periods" ("company_id", "id")
