CREATE TABLE "accounting_provider_switches" (
    "id" TEXT NOT NULL CONSTRAINT "PK_accounting_provider_switches" PRIMARY KEY,
    "company_id" TEXT NOT NULL,
    "source_kind" TEXT NOT NULL,
    "source_provider_key" TEXT NULL,
    "target_kind" TEXT NOT NULL,
    "target_provider_key" TEXT NULL,
    "effective_fiscal_period_id" TEXT NOT NULL,
    "migration_strategy" TEXT NOT NULL,
    "reason" TEXT NOT NULL,
    "responsible_user_id" TEXT NOT NULL,
    "responsible_agent_id" TEXT NULL,
    "status" TEXT NOT NULL,
    "blocked_from_status" TEXT NULL,
    "failure_code" TEXT NULL,
    "failure_summary" TEXT NULL,
    "created_by_user_id" TEXT NOT NULL,
    "updated_by_user_id" TEXT NOT NULL,
    "cancelled_by_user_id" TEXT NULL,
    "cancellation_reason" TEXT NULL,
    "correlation_id" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "status_changed_at" TEXT NOT NULL,
    "blocked_at" TEXT NULL,
    "cancelled_at" TEXT NULL,
    "completed_at" TEXT NULL,
    "version" INTEGER NOT NULL,
    CONSTRAINT "AK_accounting_provider_switches_company_id_id" UNIQUE ("company_id", "id"),
    CONSTRAINT "CK_accounting_provider_switches_cancellation" CHECK (([status] = 'cancelled' AND [cancelled_at] IS NOT NULL AND [cancelled_by_user_id] IS NOT NULL AND [cancellation_reason] IS NOT NULL) OR ([status] <> 'cancelled' AND [cancelled_at] IS NULL AND [cancelled_by_user_id] IS NULL AND [cancellation_reason] IS NULL)),
    CONSTRAINT "CK_accounting_provider_switches_distinct_endpoints" CHECK (NOT ([source_kind] = [target_kind] AND COALESCE([source_provider_key], '') = COALESCE([target_provider_key], ''))),
    CONSTRAINT "CK_accounting_provider_switches_source_endpoint" CHECK (([source_kind] = 'internal' AND [source_provider_key] IS NULL) OR ([source_kind] = 'external' AND [source_provider_key] IS NOT NULL)),
    CONSTRAINT "CK_accounting_provider_switches_status" CHECK ([status] IN ('draft', 'assessing', 'ready_for_planning', 'plan_awaiting_approval', 'preparing_target', 'rehearsal_passed', 'scheduled', 'source_frozen', 'reconciling', 'activation_awaiting_approval', 'target_authoritative', 'monitoring', 'completed', 'blocked', 'cancelled', 'recovery')),
    CONSTRAINT "CK_accounting_provider_switches_strategy" CHECK ([migration_strategy] IN ('opening_balances_and_open_items', 'current_fiscal_year', 'full_history')),
    CONSTRAINT "CK_accounting_provider_switches_target_endpoint" CHECK (([target_kind] = 'internal' AND [target_provider_key] IS NULL) OR ([target_kind] = 'external' AND [target_provider_key] IS NOT NULL)),
    CONSTRAINT "CK_accounting_provider_switches_version" CHECK ([version] > 0),
    CONSTRAINT "FK_accounting_provider_switches_agents_company_id_responsible_agent_id" FOREIGN KEY ("company_id", "responsible_agent_id") REFERENCES "agents" ("CompanyId", "Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_accounting_provider_switches_companies_company_id" FOREIGN KEY ("company_id") REFERENCES "companies" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_accounting_provider_switches_finance_fiscal_periods_effective_fiscal_period_id" FOREIGN KEY ("effective_fiscal_period_id") REFERENCES "finance_fiscal_periods" ("id") ON DELETE RESTRICT
);


