CREATE TABLE "finance_assets" (
    "id" TEXT NOT NULL CONSTRAINT "PK_finance_assets" PRIMARY KEY,
    "company_id" TEXT NOT NULL,
    "counterparty_id" TEXT NOT NULL,
    "reference_number" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "purchased_at" TEXT NOT NULL,
    "amount" decimal(18,2) NOT NULL,
    "currency" TEXT NOT NULL,
    "funding_behavior" TEXT NOT NULL,
    "funding_settlement_status" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "source_simulation_event_record_id" TEXT NULL,
    "finance_external_reference_id" TEXT NULL,
    "provider_external_id" TEXT NULL,
    "provider_key" TEXT NULL,
    "source_type" TEXT NOT NULL DEFAULT 'manual',
    CONSTRAINT "AK_finance_assets_company_id_id" UNIQUE ("company_id", "id"),
    CONSTRAINT "CK_finance_assets_amount_positive" CHECK (amount > 0),
    CONSTRAINT "CK_finance_assets_funding_behavior" CHECK (funding_behavior IN ('cash', 'payable')),
    CONSTRAINT "CK_finance_assets_funding_settlement_status" CHECK (funding_settlement_status IN ('unpaid', 'partially_paid', 'paid', 'credited')),
    CONSTRAINT "CK_finance_assets_source_type" CHECK (source_type IN ('manual', 'simulation', 'fortnox')),
    CONSTRAINT "CK_finance_assets_status" CHECK (status IN ('active', 'disposed')),
    CONSTRAINT "FK_finance_assets_companies_company_id" FOREIGN KEY ("company_id") REFERENCES "companies" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_finance_assets_finance_counterparties_company_id_counterparty_id" FOREIGN KEY ("company_id", "counterparty_id") REFERENCES "finance_counterparties" ("company_id", "id") ON DELETE RESTRICT,
    CONSTRAINT "FK_finance_assets_finance_external_references_finance_external_reference_id" FOREIGN KEY ("finance_external_reference_id") REFERENCES "finance_external_references" ("id") ON DELETE RESTRICT,
    CONSTRAINT "FK_finance_assets_simulation_event_records_company_id_source_simulation_event_record_id" FOREIGN KEY ("company_id", "source_simulation_event_record_id") REFERENCES "simulation_event_records" ("company_id", "id") ON DELETE RESTRICT
);


CREATE TABLE "finance_bills" (
    "id" TEXT NOT NULL CONSTRAINT "PK_finance_bills" PRIMARY KEY,
    "company_id" TEXT NOT NULL,
    "counterparty_id" TEXT NOT NULL,
    "bill_number" TEXT NOT NULL,
    "received_at" TEXT NOT NULL,
    "due_at" TEXT NOT NULL,
    "amount" decimal(18,2) NOT NULL,
    "paid_amount" decimal(18,2) NOT NULL DEFAULT '0.0',
    "currency" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "settlement_status" TEXT NOT NULL DEFAULT 'unpaid',
    "posting_status" TEXT NOT NULL DEFAULT 'booked',
    "due_status" TEXT NOT NULL DEFAULT 'not_due',
    "document_kind" TEXT NOT NULL DEFAULT 'supplier_invoice',
    "provider_status" TEXT NULL,
    "processing_status" TEXT NOT NULL DEFAULT 'none',
    "document_id" TEXT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "source_simulation_event_record_id" TEXT NULL,
    "source_detected_bill_id" TEXT NULL,
    "finance_external_reference_id" TEXT NULL,
    "provider_external_id" TEXT NULL,
    "provider_key" TEXT NULL,
    "source_type" TEXT NOT NULL DEFAULT 'manual',
    CONSTRAINT "AK_finance_bills_company_id_id" UNIQUE ("company_id", "id"),
    CONSTRAINT "CK_finance_bills_document_kind" CHECK (document_kind IN ('invoice', 'credit_note', 'supplier_invoice', 'supplier_credit_note')),
    CONSTRAINT "CK_finance_bills_due_status" CHECK (due_status IN ('not_due', 'due_soon', 'overdue')),
    CONSTRAINT "CK_finance_bills_paid_amount_non_negative" CHECK (paid_amount >= 0),
    CONSTRAINT "CK_finance_bills_posting_status" CHECK (posting_status IN ('draft', 'booked', 'cancelled')),
    CONSTRAINT "CK_finance_bills_processing_status" CHECK (processing_status IN ('none', 'payment_pending', 'authorization_pending')),
    CONSTRAINT "CK_finance_bills_settlement_status" CHECK (settlement_status IN ('unpaid', 'partially_paid', 'paid', 'credited')),
    CONSTRAINT "CK_finance_bills_source_type" CHECK (source_type IN ('manual', 'simulation', 'fortnox')),
    CONSTRAINT "FK_finance_bills_companies_company_id" FOREIGN KEY ("company_id") REFERENCES "companies" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_finance_bills_detected_bills_company_id_source_detected_bill_id" FOREIGN KEY ("company_id", "source_detected_bill_id") REFERENCES "detected_bills" ("company_id", "id"),
    CONSTRAINT "FK_finance_bills_finance_counterparties_company_id_counterparty_id" FOREIGN KEY ("company_id", "counterparty_id") REFERENCES "finance_counterparties" ("company_id", "id") ON DELETE RESTRICT,
    CONSTRAINT "FK_finance_bills_finance_external_references_finance_external_reference_id" FOREIGN KEY ("finance_external_reference_id") REFERENCES "finance_external_references" ("id") ON DELETE RESTRICT,
    CONSTRAINT "FK_finance_bills_knowledge_documents_company_id_document_id" FOREIGN KEY ("company_id", "document_id") REFERENCES "knowledge_documents" ("CompanyId", "Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_finance_bills_simulation_event_records_company_id_source_simulation_event_record_id" FOREIGN KEY ("company_id", "source_simulation_event_record_id") REFERENCES "simulation_event_records" ("company_id", "id") ON DELETE RESTRICT
);


